    "1": {
      "id": 1,
      "visual_description": "Transparent blue ring, mounted on a metallic rod extending from right side."
    },
    "2": {
      "id": 2,
      "visual_description": "Small wooden sphere with a blue band around its middle, floating and moving near the ring."
    }
  },
  "assessments": {
